import{_ as a,o as d,c as e,a as r}from"./chunks/framework.Ld7uezS_.js";const c=JSON.parse('{"title":"2. 设施操作","description":"","frontmatter":{},"headers":[],"relativePath":"skill/02-operation.md","filePath":"skill/02-operation.md","lastUpdated":1787283113000}'),l={name:"skill/02-operation.md"};function i(h,t,o,n,s,p){return d(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_2-设施操作" tabindex="-1">2. 设施操作 <a class="header-anchor" href="#_2-设施操作" aria-label="Permalink to &quot;2. 设施操作&quot;">​</a></h1><h2 id="本章定位" tabindex="-1">本章定位 <a class="header-anchor" href="#本章定位" aria-label="Permalink to &quot;本章定位&quot;">​</a></h2><p>设施操作是两个中级职业方向共同的职业功能。学习目标不是记住“按哪个按钮”，而是能说明操作对象、控制方式、安全条件、动作结果、反馈信号和恢复状态。</p><h2 id="一、统一操作框架" tabindex="-1">一、统一操作框架 <a class="header-anchor" href="#一、统一操作框架" aria-label="Permalink to &quot;一、统一操作框架&quot;">​</a></h2><h3 id="_1-确认任务和对象" tabindex="-1">1. 确认任务和对象 <a class="header-anchor" href="#_1-确认任务和对象" aria-label="Permalink to &quot;1. 确认任务和对象&quot;">​</a></h3><p>这一环不是一句“读清设备名称”就结束，而是要先学会把一条任务说明拆成 <strong>谁、在哪里、做什么、为什么做、做到什么算完成</strong> 五个问题。</p><h4 id="_1-1-什么叫-任务" tabindex="-1">1.1 什么叫“任务” <a class="header-anchor" href="#_1-1-什么叫-任务" aria-label="Permalink to &quot;1.1 什么叫“任务”&quot;">​</a></h4><p>任务就是本次要完成的工作目标，不等于一个按钮名称。常见任务可以分成几类：</p><table tabindex="0"><thead><tr><th>任务类型</th><th>零基础理解</th><th>例子</th><th>不能直接推出的结论</th></tr></thead><tbody><tr><td>查询/确认</td><td>只查看系统当前状态和历史信息</td><td>查询某区域是否有火警、故障或屏蔽</td><td>看到一条信息不等于已经找到原因</td></tr><tr><td>操作/控制</td><td>让指定设备或功能执行动作</td><td>按要求启动广播、查询联动状态</td><td>发出指令不等于现场设备已经动作</td></tr><tr><td>测试/验证</td><td>在授权和方案条件下模拟输入，观察系统响应</td><td>用适配工具测试探测器报警链</td><td>一次测试通过不等于所有设备都合格</td></tr><tr><td>恢复/收口</td><td>把测试或操作留下的临时状态恢复</td><td>恢复自动、联动、监视和阀门状态</td><td>消音或复位不等于故障已经排除</td></tr><tr><td>报告/交接</td><td>把现象、影响和处理状态交给下一责任人</td><td>记录风机无反馈并报告维修</td><td>写“已处理”不等于已经修复</td></tr></tbody></table><p>先判断任务类型，再决定能不能操作。比如“查看某区域火警记录”和“启动某区域排烟风机”不是同一种任务，前者主要读取信息，后者会影响现场设备和人员安全，所需授权、监护和恢复安排不同。</p><h4 id="_1-2-什么叫-对象" tabindex="-1">1.2 什么叫“对象” <a class="header-anchor" href="#_1-2-什么叫-对象" aria-label="Permalink to &quot;1.2 什么叫“对象”&quot;">​</a></h4><p>对象是本次任务真正针对的设备、部件、控制功能或信息点。消防设施中至少有四层对象：</p><ol><li><strong>输入对象</strong>：探测器、手动火灾报警按钮、水流指示器、压力开关等，负责产生或提供状态信息；</li><li><strong>控制对象</strong>：火灾报警控制器、消防联动控制器、控制柜、模块等，负责接收信息、判断或发出指令；</li><li><strong>执行对象</strong>：消防泵、风机、风阀、广播、卷帘、应急照明等，负责改变现场状态；</li><li><strong>反馈对象</strong>：运行触点、到位开关、故障触点、输入模块和控制器显示等，负责证明动作结果或异常状态。</li></ol><p>因此，“操作报警系统”还不够具体，必须继续问：是查看控制器信息、测试探测器输入、操作输出模块，还是核对现场风机反馈？对象层级不同，动作风险和判断方法也不同。</p><h4 id="_1-3-什么叫-区域" tabindex="-1">1.3 什么叫“区域” <a class="header-anchor" href="#_1-3-什么叫-区域" aria-label="Permalink to &quot;1.3 什么叫“区域”&quot;">​</a></h4><p>区域不是随便说的“这一层”或“附近”，而是任务依据中能够被定位和区分的保护范围或设备位置。常见定位信息包括：</p><ul><li>建筑、楼栋、楼层、房间或防火分区；</li><li>报警区域、探测区域、联动区域或防烟分区；</li><li>控制器回路、设备地址、模块编号、泵房/风机房等设备位置；</li><li>水系统的保护分区、末端试水点、阀组编号或管网分区。</li></ul><p>实际确认时，应把“文字区域”与“图纸、控制器地址、设备铭牌和现场位置”相互核对。只看到控制器上的一个名称，不能直接假定现场就是该位置；同名房间、相邻防火分区或相邻设备都可能造成误操作。</p><h4 id="_1-4-什么叫-操作目的和完成标准" tabindex="-1">1.4 什么叫“操作目的和完成标准” <a class="header-anchor" href="#_1-4-什么叫-操作目的和完成标准" aria-label="Permalink to &quot;1.4 什么叫“操作目的和完成标准”&quot;">​</a></h4><p>操作目的回答“为什么做”，完成标准回答“看到什么证据才算本次任务收口”。例如：</p><ul><li>目的为确认广播是否覆盖指定区域：不能只看控制器显示输出，还要核对目标区域实际可听、分区是否正确以及测试后是否恢复；</li><li>目的为确认风机联动链：要区分联动条件、控制器输出、风机现场运行、风阀位置和反馈信号，不能只写“风机启动”；</li><li>目的为查询某点故障：要记录设备地址、故障类别、发生时间和当前影响，不能直接按复位把信息抹掉；</li><li>目的为恢复系统：要逐项确认火警/故障/屏蔽状态、自动/联动/监视状态、现场设备位置和临时防护是否收口。</li></ul><h4 id="_1-5-零基础-五问确认法" tabindex="-1">1.5 零基础“五问确认法” <a class="header-anchor" href="#_1-5-零基础-五问确认法" aria-label="Permalink to &quot;1.5 零基础“五问确认法”&quot;">​</a></h4><p>拿到任何操作任务，先用下面的话复述一遍：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我现在要对【哪一栋/哪一层/哪一分区/哪一个地址】的【哪台设备或哪项功能】</span></span>
<span class="line"><span>执行【查询、控制、测试、恢复或交接】；</span></span>
<span class="line"><span>目的是【验证什么或处理什么】；</span></span>
<span class="line"><span>预期看到【显示、现场动作、反馈或恢复状态】；</span></span>
<span class="line"><span>结束后要恢复【自动/联动/监视、阀门、供电或其他规定状态】。</span></span></code></pre></div><p>如果这句话中的任意一项说不出来，不应直接操作，而应先查阅任务单、图纸、设备说明书、单位规程或向授权人员确认。零基础学习阶段可以先在纸上完成这五问，不需要接触真实设备。</p><h3 id="_2-确认安全条件" tabindex="-1">2. 确认安全条件 <a class="header-anchor" href="#_2-确认安全条件" aria-label="Permalink to &quot;2. 确认安全条件&quot;">​</a></h3><p>确认人员已避开运动部件和危险区域，联动影响已告知，控制方式和授权正确，必要的隔离、监护和警示已经落实。</p><h3 id="_3-选择控制方式" tabindex="-1">3. 选择控制方式 <a class="header-anchor" href="#_3-选择控制方式" aria-label="Permalink to &quot;3. 选择控制方式&quot;">​</a></h3><p>区分就地/远程、手动/自动、主泵/备泵、主电/备电等状态。控制方式不同，设备是否会联动、反馈是否出现也可能不同。</p><h3 id="_4-执行并观察" tabindex="-1">4. 执行并观察 <a class="header-anchor" href="#_4-执行并观察" aria-label="Permalink to &quot;4. 执行并观察&quot;">​</a></h3><p>按设备说明书和鉴定站评分表操作，同时观察控制器显示、现场动作、指示灯、压力/风阀位置、声光效果和反馈信号。</p><h3 id="_5-恢复并记录" tabindex="-1">5. 恢复并记录 <a class="header-anchor" href="#_5-恢复并记录" aria-label="Permalink to &quot;5. 恢复并记录&quot;">​</a></h3><p>按任务要求停止、复位、恢复自动/联动/监视状态，确认无新增故障，填写记录并报告异常。</p><h2 id="二、先理解-控制方式-为什么会改变结果" tabindex="-1">二、先理解“控制方式”为什么会改变结果 <a class="header-anchor" href="#二、先理解-控制方式-为什么会改变结果" aria-label="Permalink to &quot;二、先理解“控制方式”为什么会改变结果&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制方式</th><th>零基础理解</th><th>可能带来的差异</th></tr></thead><tbody><tr><td>就地控制</td><td>在设备附近通过本地按钮、柜体或机构操作</td><td>需要确认现场人员、运动部件和本地状态</td></tr><tr><td>远程控制</td><td>在控制室或远端控制设备</td><td>需要确认通信、权限、联动条件和现场反馈</td></tr><tr><td>手动控制</td><td>由人员发出明确操作指令</td><td>不代表设备一定动作，还要观察执行和反馈</td></tr><tr><td>自动控制</td><td>满足设计逻辑和条件后系统自动输出</td><td>不能擅自假设所有输入都会触发同一联动</td></tr><tr><td>主泵/备用泵</td><td>主设备和备用设备按设计承担供水任务</td><td>供电、优先级、切换和反馈可能不同</td></tr></tbody></table><p>控制器“显示手动”不是故障本身，但意味着不能直接假设系统会自动联动；恢复结束时要把控制方式作为独立结果记录。</p><h3 id="每张操作卡都要写清三类结果" tabindex="-1">每张操作卡都要写清三类结果 <a class="header-anchor" href="#每张操作卡都要写清三类结果" aria-label="Permalink to &quot;每张操作卡都要写清三类结果&quot;">​</a></h3><ul><li><strong>预期结果</strong>：按方案执行后，控制器、现场设备和反馈分别应出现什么；</li><li><strong>异常分支</strong>：没有输出、输出未动作、动作无反馈、动作后未恢复分别怎么记录和升级；</li><li><strong>结束条件</strong>：自动/联动/监视、阀门、供电、现场安全和记录是否恢复。</li></ul><h2 id="三、火灾报警和联动控制" tabindex="-1">三、火灾报警和联动控制 <a class="header-anchor" href="#三、火灾报警和联动控制" aria-label="Permalink to &quot;三、火灾报警和联动控制&quot;">​</a></h2><p>零基础先认识三类对象：输入设备（探测器、按钮、压力开关等）、控制设备（报警/联动控制器）、输出设备（泵、风机、广播、卷帘等）。训练时每次都回答：输入是什么？控制器显示什么？输出设备动作什么？反馈从哪里回来？</p><p>常见训练内容包括火警/故障查询、消音、复位、手动/自动识别、联动控制盘操作和状态恢复。具体按钮、密码、菜单和权限必须按现场设备说明书执行。</p><h2 id="四、设备级操作卡" tabindex="-1">四、设备级操作卡 <a class="header-anchor" href="#四、设备级操作卡" aria-label="Permalink to &quot;四、设备级操作卡&quot;">​</a></h2><p>下面不是固定品牌的按钮教程，而是进入任何实操题前都要能说清的“对象—条件—动作—反馈—恢复”卡。菜单名称、密码、端子和按钮位置必须以现场设备说明书和鉴定站评分表为准。</p><h3 id="_1-火灾自动报警系统操作卡" tabindex="-1">1. 火灾自动报警系统操作卡 <a class="header-anchor" href="#_1-火灾自动报警系统操作卡" aria-label="Permalink to &quot;1. 火灾自动报警系统操作卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>学习要点</th></tr></thead><tbody><tr><td>对象识别</td><td>区分探测器、手动火灾报警按钮、输入模块、输出模块、报警控制器、联动控制器和火灾警报装置。</td></tr><tr><td>操作前</td><td>核对区域、任务、授权、控制方式、当前火警/故障/屏蔽状态，确认不会误启动现场设备。</td></tr><tr><td>执行动作</td><td>按方案触发或操作目标功能；涉及联动输出时，先确认人员、设备和动作区域安全。</td></tr><tr><td>结果观察</td><td>同时看控制器显示、现场声光/执行机构动作、运行状态和反馈信号；“输出已发出”不等于“现场已动作”。</td></tr><tr><td>恢复记录</td><td>按要求消音、复位或恢复自动/联动/监视，确认无新增故障，记录原始状态、动作、反馈和异常。</td></tr></tbody></table><p>**典型判断：**控制器显示火警时，不能因为现场暂未发现明火就直接复位；应先按预案核实、报告并判断处置。控制器显示故障时，不能用拔线、屏蔽或断电代替故障处理。</p><h3 id="_2-消防给水和自动灭火系统操作卡" tabindex="-1">2. 消防给水和自动灭火系统操作卡 <a class="header-anchor" href="#_2-消防给水和自动灭火系统操作卡" aria-label="Permalink to &quot;2. 消防给水和自动灭火系统操作卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>学习要点</th></tr></thead><tbody><tr><td>对象识别</td><td>区分水源、水池/水箱、消防泵、稳压泵、控制柜、报警阀组、控制阀、水流指示器、压力开关和末端试水装置。</td></tr><tr><td>操作前</td><td>核对测试区域、供水范围、阀门状态、电源、控制方式、排水条件和人员安全；放水或启泵必须有授权。</td></tr><tr><td>执行动作</td><td>按任务选择就地/远程、手动/自动或规定测试方式，观察启动、运行和压力变化，不擅自关闭保护阀门。</td></tr><tr><td>结果观察</td><td>核对泵组运行、控制柜指示、管网压力、水流/压力信号、控制器显示和现场有无渗漏。</td></tr><tr><td>恢复记录</td><td>按方案停止或恢复自动，关闭试水装置并确认排水、阀门、控制柜和监视状态，记录测试点和异常。</td></tr></tbody></table><p>**边界：**泵电机转动只说明出现运行现象，不能单独证明供水能力合格；末端有水也不能推算全系统性能。湿式、干式、预作用、雨淋等系统的具体操作必须先确认现场系统形式和依据。</p><h3 id="_3-其他消防设施操作卡" tabindex="-1">3. 其他消防设施操作卡 <a class="header-anchor" href="#_3-其他消防设施操作卡" aria-label="Permalink to &quot;3. 其他消防设施操作卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对象</th><th>操作前</th><th>必须核对的结果</th></tr></thead><tbody><tr><td>防烟排烟</td><td>确认人员疏散影响、风机/风阀区域和授权</td><td>风机动作、风阀位置、控制器反馈、故障状态</td></tr><tr><td>防火门/卷帘/防火阀</td><td>清空运动区域，确认无人、无障碍和限位风险</td><td>启停/升降、到位、限位、现场安全和反馈</td></tr><tr><td>应急照明/疏散指示</td><td>确认测试范围和供电方式，不遮挡疏散路径</td><td>灯具状态、集中电源/控制器状态、故障信息</td></tr><tr><td>消防广播/电话</td><td>核对目标分区、话筒或分机、内容和音量</td><td>目标区域可听、通话接通清晰、控制室状态和恢复</td></tr><tr><td>消防电梯迫降</td><td>仅按预案、授权和现场条件执行</td><td>迫降信号、相关反馈、设备状态和恢复条件</td></tr></tbody></table><p>**共同结束条件：**动作已停止不等于任务完成。必须确认规定的自动、联动、监视或常态状态已恢复；不能恢复时要保留异常、报告并落实临时防护。</p><h2 id="五、消防泵组" tabindex="-1">五、消防泵组 <a class="header-anchor" href="#五、消防泵组" aria-label="Permalink to &quot;五、消防泵组&quot;">​</a></h2><h3 id="设备认知" tabindex="-1">设备认知 <a class="header-anchor" href="#设备认知" aria-label="Permalink to &quot;设备认知&quot;">​</a></h3><p>识别消防水泵、稳压泵、控制柜、压力表、阀门、水泵接合器、启泵按钮和反馈模块。</p><h3 id="操作时观察什么" tabindex="-1">操作时观察什么 <a class="header-anchor" href="#操作时观察什么" aria-label="Permalink to &quot;操作时观察什么&quot;">​</a></h3><ul><li>启动前：电源、控制方式、阀门、管网和区域安全；</li><li>启动中：泵是否运行、压力变化、异常声音/振动、控制柜指示；</li><li>启动后：主备泵、压力开关、控制器反馈和现场状态；</li><li>结束时：停泵权限、阀门状态、自动状态和记录。</li></ul><p>不要在没有确认的情况下切断电源或关闭阀门，也不要把泵电机转动当作供水功能已经合格。</p><h2 id="六、防烟排烟" tabindex="-1">六、防烟排烟 <a class="header-anchor" href="#六、防烟排烟" aria-label="Permalink to &quot;六、防烟排烟&quot;">​</a></h2><p>识别送风机、排烟风机、风阀、排烟口、送风口和控制柜。操作后同时确认风机动作、风阀开闭、控制器反馈和现场气流/状态。防排烟系统涉及人员疏散，不能为演示随意改变系统运行状态。</p><h2 id="七、应急广播和消防电话" tabindex="-1">七、应急广播和消防电话 <a class="header-anchor" href="#七、应急广播和消防电话" aria-label="Permalink to &quot;七、应急广播和消防电话&quot;">​</a></h2><p>广播操作要确认目标分区、话筒/音量、广播内容和目标区域是否听清；消防电话操作要确认分机、主机接通和通话清晰。普通背景广播和消防应急广播不能混淆。</p><h2 id="八、防火卷帘和电梯迫降" tabindex="-1">八、防火卷帘和电梯迫降 <a class="header-anchor" href="#八、防火卷帘和电梯迫降" aria-label="Permalink to &quot;八、防火卷帘和电梯迫降&quot;">​</a></h2><p>卷帘操作前清空下方区域并确认授权，操作后核对上升/下降/停止、限位和反馈。电梯迫降必须按预案和授权执行，确认相关信号和状态，不把迫降当成无条件的日常试验。</p><h2 id="九、训练记录" tabindex="-1">九、训练记录 <a class="header-anchor" href="#九、训练记录" aria-label="Permalink to &quot;九、训练记录&quot;">​</a></h2><p>每次练习记录：任务、设备、操作前状态、控制方式、动作结果、反馈结果、恢复状态、异常和指导人员。记录的目的不是应付形式，而是帮助你发现“动作了但没反馈”“复位了但未恢复自动”等问题。</p><h2 id="十、自测" tabindex="-1">十、自测 <a class="header-anchor" href="#十、自测" aria-label="Permalink to &quot;十、自测&quot;">​</a></h2><ol><li>为什么操作前必须确认手动/自动状态？</li><li>启动消防泵后要看哪些反馈？</li><li>风机动作了，为什么还要检查风阀和反馈？</li><li>防火卷帘操作前最重要的现场安全确认是什么？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a>；具体设备操作和评分点以鉴定站现场要求为准。</p></blockquote>`,69)])])}const u=a(l,[["render",i]]);export{c as __pageData,u as default};
